import lens

TARGET = "adjacency_dir"
DEPTH = 2

resp = lens.callers(TARGET, depth=DEPTH)
nodes = resp.get("nodes", [])

candidates = {}
for n in nodes:
    name = n.get("name")
    file = n.get("file", "")
    if name == TARGET or not file.startswith("src/"):
        continue
    if n.get("origin", "prod") != "prod":
        continue
    candidates[name] = file

def sig_block(text, name):
    lines = text.splitlines()
    for i, line in enumerate(lines):
        if f"fn {name}(" in line or f"fn {name}<" in line:
            block = []
            for l in lines[i:i + 8]:
                block.append(l)
                if "{" in l:
                    break
            return "\n".join(block)
    return ""

skel_cache = {}
with_depth = []
for name, file in candidates.items():
    if file not in skel_cache:
        sk = lens.skeleton(file)
        skel_cache[file] = sk.get("skeleton", "") if isinstance(sk, dict) else str(sk)
    if "depth" in sig_block(skel_cache[file], name):
        with_depth.append(name)

with_depth.sort()
print(f"target=adjacency_dir transitive_callers={len(candidates)} with_depth_param={len(with_depth)}")
print(",".join(with_depth))
